import { Controller, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 자료 구분 값은 명세에 없어 전표·거래처·계정과목 세 가지로 정한다.
// 가정: 세무회계사무소 제공 양식이 없어 컬럼은 아래 목록으로 정하고, 엑셀(SpreadsheetML) XML 문서로 만든다.
const COLUMNS: Record<string, [string, string][]> = {
  VOUCHER: [
    ['voucherNo', '전표번호'],
    ['voucherDate', '전표일자'],
    ['accountCode', '계정과목 코드'],
    ['accountName', '계정과목명'],
    ['dcType', '차대 구분'],
    ['amount', '금액'],
    ['partnerName', '거래처'],
    ['summary', '적요'],
  ],
  PARTNER: [
    ['partnerCode', '거래처 코드'],
    ['partnerName', '거래처 명칭'],
    ['businessRegNo', '사업자등록번호'],
    ['representativeName', '대표자명'],
  ],
  ACCOUNT_ITEM: [
    ['accountCode', '계정과목 코드'],
    ['accountName', '계정과목명'],
    ['accountType', '계정 유형'],
  ],
};

const PERIOD_VOUCHER = `v.voucher_date BETWEEN CAST(:startDate AS date) AND CAST(:endDate AS date)`;

const QUERIES: Record<string, string> = {
  VOUCHER: `SELECT v.voucher_no AS "voucherNo",
    to_char(v.voucher_date, 'YYYY-MM-DD') AS "voucherDate",
    a.account_code AS "accountCode",
    a.account_name AS "accountName",
    l.dc_type AS "dcType",
    l.amount AS "amount",
    p.partner_name AS "partnerName",
    l.summary AS "summary"
  FROM voucher_line l
  JOIN journal_voucher v ON v.journal_voucher_id = l.journal_voucher_id
  JOIN account_item a ON a.account_item_id = l.account_item_id
  LEFT JOIN partner p ON p.partner_id = l.partner_id
  WHERE ${PERIOD_VOUCHER}
  ORDER BY v.voucher_date, v.journal_voucher_id, l.line_no`,
  PARTNER: `SELECT p.partner_code AS "partnerCode",
    p.partner_name AS "partnerName",
    p.business_reg_no AS "businessRegNo",
    p.representative_name AS "representativeName"
  FROM partner p
  WHERE EXISTS (
    SELECT 1 FROM voucher_line l
    JOIN journal_voucher v ON v.journal_voucher_id = l.journal_voucher_id
    WHERE l.partner_id = p.partner_id AND ${PERIOD_VOUCHER}
  )
  ORDER BY p.partner_code`,
  ACCOUNT_ITEM: `SELECT a.account_code AS "accountCode",
    a.account_name AS "accountName",
    a.account_type AS "accountType"
  FROM account_item a
  WHERE EXISTS (
    SELECT 1 FROM voucher_line l
    JOIN journal_voucher v ON v.journal_voucher_id = l.journal_voucher_id
    WHERE l.account_item_id = a.account_item_id AND ${PERIOD_VOUCHER}
  )
  ORDER BY a.account_code`,
};

function escapeXml(value: unknown): string {
  return String(value === null || value === undefined ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function toExcelXml(columns: [string, string][], rows: Record<string, unknown>[]): string {
  const cell = (v: unknown) => `<Cell><Data ss:Type="String">${escapeXml(v)}</Data></Cell>`;
  const head = `<Row>${columns.map((c) => cell(c[1])).join('')}</Row>`;
  const body = rows
    .map((r) => `<Row>${columns.map((c) => cell(r[c[0]])).join('')}</Row>`)
    .join('');
  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">',
    '<Worksheet ss:Name="회계자료"><Table>',
    head,
    body,
    '</Table></Worksheet>',
    '</Workbook>',
  ].join('');
}

function requireDate(value: unknown, label: string): string {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    throw new ApiError(400, 'VALIDATION_FAILED', `${label}을(를) YYYY-MM-DD 형식으로 입력해 주세요.`);
  }
  return value;
}

@Controller('api/v1')
export class FnSfr00606Controller {
  @Post('/tax-office-exports')
  @HttpCode(200)
  async exportTaxOfficeExcel(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const data = checks.inputOf(req.body);
    const startDate = requireDate(data['startDate'], '시작일');
    const endDate = requireDate(data['endDate'], '종료일');
    if (startDate > endDate) {
      throw new ApiError(400, 'VALIDATION_FAILED', '시작일은 종료일보다 늦을 수 없습니다.');
    }
    const dataType = data['dataType'];
    if (typeof dataType !== 'string' || !(dataType in QUERIES)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '자료 구분을 선택해 주세요.');
    }
    return transaction(async (db) => {
      const rows = await db.query(QUERIES[dataType], { startDate, endDate });
      if (rows.length === 0) {
        throw new ApiError(404, 'EXPORT_DATA_NOT_FOUND', '변환할 회계자료가 없습니다.');
      }
      let file: string;
      try {
        file = toExcelXml(COLUMNS[dataType], rows as Record<string, unknown>[]);
      } catch (e) {
        throw new ApiError(422, 'EXPORT_CONVERT_FAILED', '엑셀 변환 중 오류가 발생했습니다. 자료를 확인한 뒤 다시 시도해 주세요.');
      }
      return { file };
    });
  }
}

