import { useState } from 'react';
import {
  PageProps,
  Row,
  call,
  Band,
  DataTable,
  Drawer,
  Form,
  Field,
  DateInput,
  Select,
  Tiles,
  DateText,
} from '../kit';

const TYPES: [string, string][] = [
  ['VOUCHER', '전표'],
  ['PARTNER', '거래처'],
  ['ACCOUNT_ITEM', '계정과목'],
];

function typeName(value: unknown): string {
  const found = TYPES.find((t) => t[0] === value);
  return found ? found[1] : String(value);
}

function download(file: string, name: string) {
  const blob = new Blob([file], { type: 'application/vnd.ms-excel' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = name;
  a.click();
  URL.revokeObjectURL(url);
}

export default function FnSfr00606Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [dataType, setDataType] = useState('');
  const [history, setHistory] = useState<Row[]>([]);

  const fileName = (r: Row) => `세무회계자료_${String(r.dataType)}_${String(r.startDate)}_${String(r.endDate)}.xls`;

  const submit = async () => {
    if (!startDate || !endDate || !dataType) {
      throw new Error('대상 기간과 자료 구분을 모두 입력해 주세요.');
    }
    if (startDate > endDate) {
      throw new Error('시작일은 종료일보다 늦을 수 없습니다.');
    }
    const res = await call<{ file: string }>('POST', '/tax-office-exports', role, { startDate, endDate, dataType });
    const item: Row = {
      id: history.length + 1,
      dataType,
      startDate,
      endDate,
      file: res.file,
      createdAt: new Date().toISOString(),
    };
    setHistory([item, ...history]);
    download(res.file, fileName(item));
    notify('엑셀 파일로 변환했습니다.');
    setOpen(false);
  };

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>이번 변환</h2>
        <Tiles items={[['변환 건수', history.length]]} />
      </section>
      <section className="box span-8">
        <h2>변환 내역</h2>
        <Band total={history.length}>
          <button type="button" onClick={() => setOpen(true)}>
            엑셀 변환
          </button>
        </Band>
        <DataTable
          rows={history}
          empty="변환한 내역이 없습니다."
          columns={[
            { key: 'dataType', label: '자료 구분', render: (r) => typeName(r.dataType) },
            { key: 'startDate', label: '시작일', render: (r) => <DateText value={r.startDate} /> },
            { key: 'endDate', label: '종료일', render: (r) => <DateText value={r.endDate} /> },
            { key: 'createdAt', label: '변환 시각', render: (r) => <DateText value={r.createdAt} time /> },
            {
              key: 'file',
              label: '파일',
              render: (r) => (
                <button type="button" onClick={() => download(String(r.file), fileName(r))}>
                  다운로드
                </button>
              ),
            },
          ]}
        />
      </section>
      {open && (
        <Drawer title="세무회계사무소 연계용 엑셀 변환" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="변환 및 다운로드">
            <Field label="변환 대상 기간 시작일" required>
              <DateInput value={startDate} onChange={setStartDate} />
            </Field>
            <Field label="변환 대상 기간 종료일" required>
              <DateInput value={endDate} onChange={setEndDate} />
            </Field>
            <Field label="변환 대상 자료 구분" required>
              <Select value={dataType} onChange={setDataType} options={TYPES} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
